values ('aaaa0006-0000-4000-8000-000000000002', 'en', null, 'German A2 — Everyday Life', 'A CEFR A2 course that builds on German basics for elementary learners: shop, describe your daily routine, talk about the past with the Perfekt, make plans, ask for directions, and use modal verbs with confidence.', 'A2', 'daily_life', 11, true, 'language', '{aaaa0006-0000-4000-8000-000000000001}')
