insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'aaaa0006-0000-4000-8000-000000000002', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Shopping & groceries', 'vocab', '{"items":[{"term":"der Supermarkt","translation":"the supermarket","ipa":"deːɐ̯ ˈzuːpɐˌmaʁkt","example":"Ich gehe heute in den Supermarkt."},{"term":"einkaufen","translation":"to shop / go shopping","ipa":"ˈaɪnˌkaʊfn̩","example":"Am Samstag kaufen wir für die ganze Woche ein."},{"term":"die Kasse","translation":"the checkout / till","ipa":"diː ˈkasə","example":"Bitte bezahlen Sie an der Kasse."},{"term":"Was kostet…?","translation":"how much is…?","ipa":"vas ˈkɔstət","example":"Was kostet ein Kilo Tomaten?"},{"term":"die Tüte","translation":"the bag","ipa":"diː ˈtyːtə","example":"Brauchen Sie eine Tüte?"},{"term":"im Angebot","translation":"on offer / on sale","ipa":"ɪm ˈanɡəˌboːt","example":"Der Käse ist heute im Angebot."}]}'::jsonb, 'After brauchen, kaufen and möchten the noun is a direct object, so masculine der becomes den: Ich brauche den Käse, ich kaufe einen Apfel. This is the accusative case in action.', 9),
  (2, 'My daily routine', 'vocab', '{"items":[{"term":"aufstehen","translation":"to get up","ipa":"ˈaʊfˌʃteːən","example":"Ich stehe jeden Tag um halb sieben auf."},{"term":"sich duschen","translation":"to shower","ipa":"zɪç ˈduːʃn̩","example":"Morgens dusche ich mich schnell."},{"term":"frühstücken","translation":"to have breakfast","ipa":"ˈfʁyːˌʃtʏkn̩","example":"Wir frühstücken zusammen in der Küche."},{"term":"zur Arbeit gehen","translation":"to go to work","ipa":"tsuːɐ̯ ˈaʁbaɪt ˈɡeːən","example":"Um acht Uhr gehe ich zur Arbeit."},{"term":"am Abend","translation":"in the evening","ipa":"am ˈaːbn̩t","example":"Am Abend koche ich und sehe fern."},{"term":"ins Bett gehen","translation":"to go to bed","ipa":"ɪns bɛt ˈɡeːən","example":"Ich gehe meistens um elf Uhr ins Bett."}]}'::jsonb, 'Many routine verbs are separable: aufstehen and anziehen split in a sentence — ich stehe um sieben Uhr auf. The prefix (auf-, an-) jumps to the very end.', 9),
  (3, 'The Perfekt: talking about the past', 'grammar', '{"sections":[{"heading":"How the Perfekt is built","text":"In everyday speech Germans describe past events with the Perfekt, not a simple past. You need two pieces: a helper verb (haben or sein) in position two, and a past participle at the very end of the sentence. Example: Ich habe einen Kaffee getrunken (I drank a coffee). The helper is conjugated, the participle never changes."},{"heading":"Building the participle","text":"Regular (weak) verbs form the participle with ge- …-t: kaufen → gekauft, machen → gemacht, spielen → gespielt. So Ich habe Brot gekauft means ''I bought bread''. Many common verbs are irregular (strong) and end in -en with a vowel change: trinken → getrunken, essen → gegessen, sehen → gesehen."},{"heading":"haben or sein?","text":"Most verbs use haben. But verbs of movement or change of state use sein: gehen → ich bin gegangen, fahren → ich bin gefahren, kommen → ich bin gekommen, bleiben → ich bin geblieben. Compare: Ich habe gearbeitet (I worked) but Ich bin nach Berlin gefahren (I travelled to Berlin)."},{"heading":"Word order in the Perfekt","text":"The helper verb stays in second position and the participle is pushed to the end, framing the sentence: Gestern habe ich meine Freundin getroffen (Yesterday I met my friend). Even with extra details the participle waits at the end: Ich habe am Wochenende einen tollen Film gesehen."}]}'::jsonb, null, 12),
  (4, 'Describing people', 'vocab', '{"items":[{"term":"groß / klein","translation":"tall, big / short, small","ipa":"ɡʁoːs klaɪn","example":"Mein Bruder ist groß und ich bin klein."},{"term":"die Haare","translation":"the hair","ipa":"diː ˈhaːʁə","example":"Sie hat lange, blonde Haare."},{"term":"freundlich","translation":"friendly","ipa":"ˈfʁɔʏntlɪç","example":"Unsere Nachbarin ist sehr freundlich."},{"term":"die Brille","translation":"the glasses","ipa":"diː ˈbʁɪlə","example":"Der Mann mit der Brille ist mein Lehrer."},{"term":"sympathisch","translation":"likeable / nice","ipa":"zʏmˈpaːtɪʃ","example":"Ich finde deinen Freund sehr sympathisch."},{"term":"aussehen","translation":"to look / appear","ipa":"ˈaʊsˌzeːən","example":"Du siehst heute müde aus."}]}'::jsonb, 'Adjectives used after sein stay in their base form: Er ist groß, sie ist freundlich. You only add endings when the adjective sits before a noun (ein großer Mann) — that comes later.', 9),
  (5, 'Modal verbs, cases & subordinate clauses', 'grammar', '{"sections":[{"heading":"Modal verbs","text":"Modal verbs express ability, wish or obligation and send a second verb (in the infinitive) to the end of the sentence: können (can), müssen (must), wollen (to want), möchten (would like), dürfen (be allowed). Example: Ich kann gut Deutsch sprechen, Wir müssen jetzt gehen, Ich möchte einen Tee trinken. The modal is conjugated; the main verb stays as an infinitive at the end."},{"heading":"Separable verbs in a sentence","text":"Separable verbs have a prefix that detaches and moves to the end in a main clause: einkaufen → Ich kaufe im Supermarkt ein; anrufen → Ich rufe dich morgen an; aufstehen → Er steht früh auf. But after a modal verb the separable verb stays whole at the end: Ich muss noch einkaufen."},{"heading":"Accusative and dative (intro)","text":"The accusative marks the direct object (what is affected): Ich sehe den Mann. The dative marks the indirect object (to/for whom): Ich gebe dem Mann das Buch. Watch the masculine article change: der → den (accusative) → dem (dative). Dative prepositions like mit, bei and zu also trigger this: mit dem Bus, bei der Arbeit."},{"heading":"Word order in subordinate clauses","text":"Conjunctions like weil (because), dass (that) and wenn (if/when) start a subordinate clause and send the conjugated verb to the very end: Ich bleibe zu Hause, weil ich krank bin. Compare the main clause Ich bin krank with the subordinate …, weil ich krank bin. The verb bin jumps to the final position after weil."}]}'::jsonb, null, 12),
  (6, 'Buying clothes', 'roleplay', '{"scenario":"You are in a clothing shop in Berlin looking for a jacket. Greet the assistant, say what you are looking for, ask for a different size and colour, try it on, ask the price, and decide whether to buy it. Use phrases like Ich suche eine Jacke, Haben Sie das in Größe M? and Kann ich das anprobieren?","persona":"A patient shop assistant who speaks only German, suggests sizes and colours, and mentions that some items are im Angebot","goal":"Find a jacket in the right size and colour, ask the price, and complete or politely decline the purchase entirely in German"}'::jsonb, null, 10),
  (7, 'Asking for directions', 'vocab', '{"items":[{"term":"Entschuldigung, wo ist…?","translation":"excuse me, where is…?","ipa":"ɛntˈʃʊldɪɡʊŋ voː ɪst","example":"Entschuldigung, wo ist der Bahnhof?"},{"term":"geradeaus","translation":"straight ahead","ipa":"ɡəˌʁaːdəˈʔaʊs","example":"Gehen Sie geradeaus bis zur Ampel."},{"term":"links / rechts","translation":"left / right","ipa":"lɪŋks ʁɛçts","example":"An der Kreuzung gehen Sie links."},{"term":"die Ampel","translation":"the traffic light","ipa":"diː ˈampl̩","example":"Die Bäckerei ist gleich nach der Ampel."},{"term":"in der Nähe","translation":"nearby / close by","ipa":"ɪn deːɐ̯ ˈnɛːə","example":"Gibt es hier in der Nähe eine Apotheke?"},{"term":"abbiegen","translation":"to turn (off)","ipa":"ˈapˌbiːɡn̩","example":"Biegen Sie an der Post rechts ab."}]}'::jsonb, 'Direction verbs take the dative with prepositions like zu and gegenüber: zum Bahnhof (zu + dem), zur Post (zu + der). The ''left/right'' phrases links and rechts never change.', 9),
  (8, 'Making plans for the weekend', 'roleplay', '{"scenario":"You call a friend to plan something together for Saturday. Suggest an activity (cinema, park or a café), agree on a time and a meeting place, and react if your friend cannot make one of the times. Use future-in-present phrases like Wollen wir…?, Hast du am Samstag Zeit? and Wann treffen wir uns?","persona":"A friendly German-speaking friend who is enthusiastic but already busy on Saturday morning, so a time has to be negotiated","goal":"Agree on an activity, a time and a meeting point for the weekend, handling one scheduling conflict in German"}'::jsonb, null, 10),
  (9, 'Reading: a weekend in Hamburg', 'reading', '{"sections":[{"heading":"The text","text":"Read Lena''s short blog post: ''Letztes Wochenende bin ich mit dem Zug nach Hamburg gefahren. Am Samstag habe ich das Miniatur Wunderland besucht und viele Fotos gemacht. Danach bin ich am Hafen spazieren gegangen und habe Fischbrötchen gegessen. Am Sonntag hat es leider geregnet, also sind wir ins Museum gegangen. Es war ein tolles Wochenende!''"},{"heading":"Understanding the past","text":"Notice how many verbs are in the Perfekt. Movement verbs take sein: ich bin gefahren (I travelled), bin gegangen (went). Other verbs take haben: ich habe besucht (visited), habe gemacht (took/made), habe gegessen (ate). The participle always lands at the end of its clause."},{"heading":"Key details","text":"Lena travelled to Hamburg by train (mit dem Zug). On Saturday she visited the Miniatur Wunderland and walked along the harbour (am Hafen). On Sunday it rained (es hat geregnet), so they went to a museum instead. She sums it up as ein tolles Wochenende — a great weekend."},{"heading":"Your turn","text":"Write three or four sentences about your own last weekend using the Perfekt. Start with Letztes Wochenende habe ich… or …bin ich… and remember to push each participle to the end. Try to use both a haben verb and a sein verb, just like Lena does."}]}'::jsonb, null, 10),
  (10, 'A2 checkpoint', 'quiz', '{"questions":[{"prompt":"Complete the Perfekt: Ich ___ einen Kaffee getrunken.","options":["bin","habe","war","hatte"],"answer":1,"explanation":"trinken uses haben in the Perfekt: Ich habe getrunken. sein (bin) is only for movement or change-of-state verbs like gehen and fahren."},{"prompt":"Which sentence correctly uses sein in the Perfekt?","options":["Ich habe nach Berlin gefahren.","Ich bin nach Berlin gefahren.","Ich habe nach Berlin gegangen.","Ich war nach Berlin gefahren."],"answer":1,"explanation":"fahren is a movement verb, so it takes sein: Ich bin nach Berlin gefahren. Movement and change-of-state verbs use sein, most others use haben."},{"prompt":"Put the separable verb correctly: ''I get up at seven.''","options":["Ich aufstehe um sieben.","Ich stehe um sieben auf.","Ich stehe auf um sieben.","Ich um sieben aufstehe."],"answer":1,"explanation":"aufstehen is separable: the prefix auf- moves to the end — Ich stehe um sieben auf. The verb stem stays in second position."},{"prompt":"Choose the correct modal-verb sentence for ''We must go now.''","options":["Wir müssen jetzt gehen.","Wir gehen müssen jetzt.","Wir müssen gehen jetzt.","Wir jetzt müssen gehen."],"answer":0,"explanation":"The modal verb müssen is conjugated in second position and the main verb gehen goes to the end as an infinitive: Wir müssen jetzt gehen."},{"prompt":"Which article is dative? ''Ich fahre mit ___ Bus.''","options":["der","den","dem","das"],"answer":2,"explanation":"The preposition mit always takes the dative, and masculine der becomes dem in the dative: mit dem Bus."},{"prompt":"Where does the verb go after weil? ''Ich bleibe zu Hause, weil ich krank ___.''","options":["bin am Anfang","bin in der Mitte","bin am Ende","brauche kein Verb"],"answer":2,"explanation":"weil is a subordinating conjunction, so the conjugated verb moves to the very end of the clause: …, weil ich krank bin."}]}'::jsonb, null, 8)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'aaaa0006-0000-4000-8000-000000000002' and l.position = v.pos
);
